// 真实后端请求封装：统一注入 zhi-project-id 头、Bearer token、解包 {code,msg,data}
export interface RequestOptions {
  method?: 'GET' | 'POST' | 'PUT' | 'DELETE'
  data?: unknown
  // 是否注入 token / 项目头，默认注入；登录接口用 token:false
  token?: string | false
  projectId?: string
  // 是否解包统一返回体 {code,msg,data}，默认 true
  raw?: boolean
}
export interface TransportInput {
  url: string
  method: NonNullable<RequestOptions['method']>
  data?: unknown
  header: Record<string, string>
  timeout: number
}
export type Transport = (input: TransportInput) => Promise<{ statusCode: number; data: unknown }>
export interface Envelope<T> { code: number; msg: string; data: T }

export interface RequestConfig { baseUrl: string; projectId: string; getToken?: () => string | undefined }

export function createRequest(transport: Transport, config: RequestConfig) {
  return async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
    const { baseUrl, projectId, getToken } = config
    if (!baseUrl) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL')
    const useToken = options.token === false ? undefined : (options.token || getToken?.())
    const header: Record<string, string> = {
      'Content-Type': 'application/json',
      'zhi-project-id': options.projectId ?? projectId,
    }
    if (useToken) header.Authorization = `Bearer ${useToken}`
    const response = await transport({
      url: `${baseUrl.replace(/\/$/, '')}/${path.replace(/^\//, '')}`,
      method: options.method ?? 'GET',
      data: options.data,
      header,
      timeout: 20000,
    })
    if (response.statusCode < 200 || response.statusCode >= 300) {
      const body = response.data as Envelope<unknown> | undefined
      const msg = body && typeof body === 'object' && 'msg' in body ? String(body.msg) : ''
      throw new Error(msg || `请求失败（HTTP ${response.statusCode}）`)
    }
    if (options.raw) return response.data as T
    const body = response.data as Envelope<T>
    if (body && typeof body === 'object' && 'code' in body) {
      if (body.code !== 200) throw new Error(body.msg || `业务异常（code ${body.code}）`)
      return body.data
    }
    return response.data as T
  }
}

// uni.request 传输实现
export const uniTransport: Transport = input => new Promise((resolve, reject) => {
  uni.request({
    url: input.url,
    method: input.method as never,
    data: input.data as Record<string, unknown> | undefined,
    header: input.header,
    timeout: input.timeout,
    success: result => resolve({ statusCode: result.statusCode, data: result.data }),
    fail: result => reject(new Error(result.errMsg?.includes('timeout') ? '请求超时，请重试' : '网络连接失败，请重试')),
  })
})

const store = {
  get: (k: string) => { try { return uni.getStorageSync(k) } catch { return '' } },
  set: (k: string, v: unknown) => { try { uni.setStorageSync(k, v) } catch { /* ignore */ } },
  remove: (k: string) => { try { uni.removeStorageSync(k) } catch { /* ignore */ } },
}

const TOKEN_KEY = 'flood-token-v1'
export function getToken(): string | undefined { const t = store.get(TOKEN_KEY); return typeof t === 'string' && t ? t : undefined }
export function setToken(token: string) { store.set(TOKEN_KEY, token) }
export function clearToken() { store.remove(TOKEN_KEY) }

export const request = createRequest(uniTransport, {
  baseUrl: (import.meta.env.VITE_API_BASE_URL as string) ?? '',
  projectId: (import.meta.env.VITE_PROJECT_ID as string) ?? 'suzhufang',
  getToken,
})

// 真实后端请求封装：注入 zhi-project-id 头、Bearer token、解包 {code,msg,data}
export interface RequestOptions {
  method?: 'GET' | 'POST' | 'PUT' | 'DELETE'
  data?: unknown
  token?: string | false
  projectId?: string
  raw?: boolean
  baseUrl?: string
}
export interface TransportInput {
  url: string
  method: NonNullable<RequestOptions['method']>
  data?: unknown
  header: Record<string, string>
  timeout: number
}
export type Transport = (input: TransportInput) => Promise<{ statusCode: number; data: unknown }>
export interface Envelope<T> { code: number; msg: string; data: T }
export interface RequestConfig { baseUrl: string; projectId: string; getToken?: () => string | undefined }

// 兼容旧签名：createRequest(transport, baseUrlString) -> 纯透传旧行为
// 新签名：createRequest(transport, configObject) -> 注入头 + 解包
export function createRequest(transport: Transport, baseUrlOrConfig: string | RequestConfig) {
  const legacy = typeof baseUrlOrConfig === 'string'
  const config: RequestConfig = legacy ? { baseUrl: baseUrlOrConfig, projectId: 'suzhufang' } : baseUrlOrConfig
  return async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
    const baseUrl = options.baseUrl ?? config.baseUrl
    if (!baseUrl) throw new Error('真实接口未配置：请设置 VITE_API_BASE_URL')
    const header: Record<string, string> = { 'Content-Type': 'application/json' }
    if (!legacy) {
      const useToken = options.token === false ? undefined : (options.token || config.getToken?.())
      header['zhi-project-id'] = options.projectId ?? config.projectId
      if (useToken) header.Authorization = `Bearer ${useToken}`
    } else if (options.token) {
      header.Authorization = `Bearer ${options.token}`
    }
    const response = await transport({
      url: `${baseUrl.replace(/\/$/, '')}/${path.replace(/^\//, '')}`,
      method: options.method ?? 'GET',
      data: options.data,
      header,
      timeout: 20000,
    })
    if (response.statusCode < 200 || response.statusCode >= 300) {
      const body = response.data as Envelope<unknown> | undefined
      const msg = body && typeof body === 'object' && 'msg' in body ? String(body.msg) : ''
      throw new Error(msg || `请求失败（HTTP ${response.statusCode}）`)
    }
    if (legacy || options.raw) return response.data as T
    const body = response.data as Envelope<T>
    if (body && typeof body === 'object' && 'code' in body) {
      if (body.code !== 200) throw new Error(body.msg || `业务异常（code ${body.code}）`)
      return body.data
    }
    return response.data as T
  }
}

export const uniTransport: Transport = input => new Promise((resolve, reject) => {
  uni.request({
    url: input.url,
    method: input.method as never,
    data: input.data as Record<string, unknown> | undefined,
    header: input.header,
    timeout: input.timeout,
    success: result => resolve({ statusCode: result.statusCode, data: result.data }),
    fail: result => reject(new Error(result.errMsg?.includes('timeout') ? '请求超时，请重试' : '网络连接失败，请重试')),
