export function getToken(): string | undefined {
  try { const t = uni.getStorageSync(TOKEN_KEY); return typeof t === 'string' && t ? t : undefined } catch { return undefined }
}
export function setToken(token: string) { try { uni.setStorageSync(TOKEN_KEY, token) } catch { /* ignore */ } }
export function clearToken() { try { uni.removeStorageSync(TOKEN_KEY) } catch { /* ignore */ } }

const env = import.meta.env as Record<string, string | undefined>
// flood 服务（9610）
export const request = createRequest(uniTransport, {
  baseUrl: env.VITE_API_BASE_URL ?? '',
