// 纯 JS AES-256-CBC + PKCS5(PKCS7) 加密，输出 base64。
// 与后端 com.zhishu.common.core.utils.AESUtil 对齐：
//   key = 'A-16-Byte-keyValA-16-Byte-keyVal' (32字节 => AES-256)
//   iv  = 'A-16-Byte-String' (16字节)
// 仅实现加密（登录密码用），解密可选。

type Word = number[]
const SBOX: number[] = []
const INV_SBOX: number[] = []
const RCON: number[] = []
;(function initTables() {
  // 生成 S-box（基于 GF(2^8) 乘法逆 + 仿射变换），避免手抄 256 项
  const p = new Uint8Array(256)
  const q = new Uint8Array(256)
  let x = 1
  for (let i = 0; i < 255; i++) {
    p[i] = x
    // x * 3 in GF(2^8)
    x ^= (x << 1) ^ (x & 0x80 ? 0x1b : 0)
    x &= 0xff
    // q[i] = x^-1 track via p; we build log/antilog
  }
  // 用对数表构造逆
  const log = new Uint8Array(256)
  const exp = new Uint8Array(256)
  let expx = 1
  for (let i = 0; i < 255; i++) {
    exp[i] = expx
    log[expx] = i
    // expx *= 3
    expx ^= (expx << 1) ^ (expx & 0x80 ? 0x1b : 0)
    expx &= 0xff
  }
  exp[255] = exp[0]
  for (let i = 2; i < 256; i++) {
    const inv = exp[(255 - log[i]) % 255]
    let s = inv
    let s2 = ((s << 1) | (s >> 7)) & 0xff
    let s3 = ((s2 << 1) | (s2 >> 7)) & 0xff
    let s4 = ((s3 << 1) | (s3 >> 7)) & 0xff
    let s5 = ((s4 << 1) | (s4 >> 7)) & 0xff
    let r = s ^ s2 ^ s3 ^ s4 ^ s5 ^ 0x63
    SBOX[i] = r & 0xff
    INV_SBOX[r & 0xff] = i
  }
  SBOX[0] = 0x63
  INV_SBOX[0x63] = 0
  let rcon = 1
  for (let i = 0; i < 15; i++) { RCON[i] = rcon; rcon = gmul(rcon, 2) }
})()

function gmul(a: number, b: number): number {
  let p = 0
  for (let i = 0; i < 8; i++) {
    if (b & 1) p ^= a
    const hi = a & 0x80
    a = (a << 1) & 0xff
    if (hi) a ^= 0x1b
    b >>= 1
  }
  return p & 0xff
}

function xtime(a: number): number { return ((a << 1) ^ (a & 0x80 ? 0x1b : 0)) & 0xff }

function expandKey(key: number[]): number[][] {
  const Nk = key.length / 4 // 8 for 256
  const Nr = Nk + 6 // 14 for 256
  const w: number[][] = []
  for (let i = 0; i < Nk; i++) w[i] = [key[4 * i], key[4 * i + 1], key[4 * i + 2], key[4 * i + 3]]
  for (let i = Nk; i < 4 * (Nr + 1); i++) {
    let temp = w[i - 1].slice()
    if (i % Nk === 0) {
      temp = [temp[1], temp[2], temp[3], temp[0]] // RotWord
      temp = temp.map(b => SBOX[b]) // SubWord
      temp[0] ^= RCON[i / Nk - 1]
    } else if (Nk > 6 && i % Nk === 4) {
      temp = temp.map(b => SBOX[b])
    }
    w[i] = w[i - Nk].map((b, j) => b ^ temp[j])
  }
  const roundKeys: number[][] = []
  for (let r = 0; r <= Nr; r++) {
    const rk: number[] = []
    for (let c = 0; c < 4; c++) rk.push(...w[4 * r + c])
    roundKeys.push(rk)
  }
  return roundKeys
}

function addRoundKey(state: number[], rk: number[]) { for (let i = 0; i < 16; i++) state[i] ^= rk[i] }

function subBytes(state: number[]) { for (let i = 0; i < 16; i++) state[i] = SBOX[state[i]] }
function invSubBytes(state: number[]) { for (let i = 0; i < 16; i++) state[i] = INV_SBOX[state[i]] }

function shiftRows(s: number[]) {
  // 列主序：state[c*4+r]
  for (let r = 1; r < 4; r++) {
    const row = [s[r], s[4 + r], s[8 + r], s[12 + r]]
    const sh = row.slice(r).concat(row.slice(0, r))
    s[r] = sh[0]; s[4 + r] = sh[1]; s[8 + r] = sh[2]; s[12 + r] = sh[3]
  }
}
function invShiftRows(s: number[]) {
  for (let r = 1; r < 4; r++) {
    const row = [s[r], s[4 + r], s[8 + r], s[12 + r]]
    const sh = row.slice(4 - r).concat(row.slice(0, 4 - r))
    s[r] = sh[0]; s[4 + r] = sh[1]; s[8 + r] = sh[2]; s[12 + r] = sh[3]
  }
}
function mixColumns(s: number[]) {
  for (let c = 0; c < 4; c++) {
    const i = 4 * c
    const a0 = s[i], a1 = s[i + 1], a2 = s[i + 2], a3 = s[i + 3]
    s[i] = gmul(a0, 2) ^ gmul(a1, 3) ^ a2 ^ a3
    s[i + 1] = a0 ^ gmul(a1, 2) ^ gmul(a2, 3) ^ a3
    s[i + 2] = a0 ^ a1 ^ gmul(a2, 2) ^ gmul(a3, 3)
