    const i = 4 * c
    const a0 = s[i], a1 = s[i + 1], a2 = s[i + 2], a3 = s[i + 3]
    s[i] = gmul(a0, 14) ^ gmul(a1, 11) ^ gmul(a2, 13) ^ gmul(a3, 9)
    s[i + 1] = gmul(a0, 9) ^ gmul(a1, 14) ^ gmul(a2, 11) ^ gmul(a3, 13)
    s[i + 2] = gmul(a0, 13) ^ gmul(a1, 9) ^ gmul(a2, 14) ^ gmul(a3, 11)
    s[i + 3] = gmul(a0, 11) ^ gmul(a1, 13) ^ gmul(a2, 9) ^ gmul(a3, 14)
  }
}

function encryptBlock(input: number[], roundKeys: number[]): number[] {
  const s = input.slice()
  addRoundKey(s, roundKeys[0])
  const Nr = roundKeys.length - 1
  for (let r = 1; r < Nr; r++) {
    subBytes(s); shiftRows(s); mixColumns(s); addRoundKey(s, roundKeys[r])
  }
  subBytes(s); shiftRows(s); addRoundKey(s, roundKeys[Nr])
