    else if ((b & 0xe0) === 0xc0) { out += String.fromCharCode(((b & 0x1f) << 6) | (bytes[i + 1] & 0x3f)); i += 2 }
    else if ((b & 0xf0) === 0xe0) { out += String.fromCharCode(((b & 0x0f) << 12) | ((bytes[i + 1] & 0x3f) << 6) | (bytes[i + 2] & 0x3f)); i += 3 }
    else { const cp = ((b & 0x07) << 18) | ((bytes[i + 1] & 0x3f) << 12) | ((bytes[i + 2] & 0x3f) << 6) | (bytes[i + 3] & 0x3f); out += String.fromCodePoint(cp); i += 4 }
  }
  return out
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
function base64Encode(bytes: number[]): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i], b1 = bytes[i + 1] ?? 0, b2 = bytes[i + 2] ?? 0
    out += B64[b0 >> 2] + B64[((b0 & 3) << 4) | (b1 >> 4)]
    out += i + 1 < bytes.length ? B64[((b1 & 15) << 2) | (b2 >> 6)] : '='
    out += i + 2 < bytes.length ? B64[b2 & 63] : '='
  }
  return out
}
function base64Decode(str: string): number[] {
  const clean = str.replace(/[^A-Za-z0-9+/]/g, '')
  const out: number[] = []
  for (let i = 0; i < clean.length; i += 4) {
    const c0 = B64.indexOf(clean[i]), c1 = B64.indexOf(clean[i + 1]), c2 = B64.indexOf(clean[i + 2]), c3 = B64.indexOf(clean[i + 3])
    out.push((c0 << 2) | (c1 >> 4))
    if (c2 >= 0) out.push(((c1 & 15) << 4) | (c2 >> 2))
    if (c3 >= 0) out.push(((c2 & 3) << 6) | c3)
  }
  return out
}

function pkcs7Pad(data: number[]): number[] {
  const pad = 16 - (data.length % 16)
  return data.concat(new Array(pad).fill(pad))
}
function pkcs7Unpad(data: number[]): number[] {
  const pad = data[data.length - 1]
  if (pad < 1 || pad > 16) return data
  return data.slice(0, data.length - pad)
}

const DEFAULT_KEY = 'A-16-Byte-keyValA-16-Byte-keyVal'
const DEFAULT_IV = 'A-16-Byte-String'

export function aesEncrypt(plain: string, key = DEFAULT_KEY, iv = DEFAULT_IV): string {
  const roundKeys = expandKey(utf8Bytes(key))
  const ivBytes = utf8Bytes(iv)
  const data = pkcs7Pad(utf8Bytes(plain))
  const out: number[] = []
  let prev = ivBytes
  for (let i = 0; i < data.length; i += 16) {
    const block = data.slice(i, i + 16).map((b, j) => b ^ prev[j])
    const enc = encryptBlock(block, roundKeys)
    out.push(...enc)
    prev = enc
  }
  return base64Encode(out)
}

export function aesDecrypt(cipherB64: string, key = DEFAULT_KEY, iv = DEFAULT_IV): string {
  const roundKeys = expandKey(utf8Bytes(key))
  const ivBytes = utf8Bytes(iv)
  const data = base64Decode(cipherB64)
  const out: number[] = []
  let prev = ivBytes
  for (let i = 0; i < data.length; i += 16) {
    const block = data.slice(i, i + 16)
    const dec = decryptBlock(block, roundKeys).map((b, j) => b ^ prev[j])
    out.push(...dec)
    prev = block
  }
  return bytesToUtf8(pkcs7Unpad(out))
}

