import { defineStore } from 'pinia'
import { hasDateField } from '../types/inspection'
import { request, authRequest, setToken, clearToken } from '../utils/request'
import { aesEncrypt } from '../utils/aes'
export type InspectionType = 'pre' | 'mid' | 'post'
export type FormValues = Record<string, unknown>
export interface StoragePort { get(key: string): unknown; set(key: string, value: unknown): void }
const key = 'flood-demo-v1'

/** 模板/记录里的一个检查项（来自后端 items[]，fillType 驱动输入控件） */
export interface FloodItem {
  templateItemId: string
  detailId?: string
  label: string
  fillType: string
  fillOptions?: string[]
  unit?: string
  value: string
  sortNo?: number
}
export interface FloodTemplate { kind: InspectionType; eventId: string; stage: string; items: FloodItem[] }
export interface RescueInfo { contactName?: string; contactPhone?: string; urgentLevel?: string; dangerDesc?: string; supportDesc?: string; attachUrl?: string }

export interface FloodRecord {
  id: string
  kind: InspectionType | 'rescue'
  status: 'submitted' | 'draft'
  createdAt: string
  inspectionNo?: string
  subject?: string
  complexId?: string
  complexName?: string
  eventId?: string
