// 阶段映射：pre->2(汛前) mid->3(汛中) post->4(汛后)
const STAGE: Record<InspectionType, string> = { pre: '2', mid: '3', post: '4' }
const KIND_BY_STAGE: Record<string, InspectionType> = { '2': 'pre', '3': 'mid', '4': 'post' }
const URGENT: Record<string, string> = { '一般': '1', '紧急': '2', '特级': '3' }

// 后端事件 / 检查单 VO 类型（宽松）
interface EventVo { eventId: string | number; eventName: string; stage: string; bizState: string }
interface PageVo<T> { total: number | string; rows: T[]; code?: number; msg?: string }
interface InspectionRow {
  inspectionId: string | number; inspectionNo?: string; inspectionStage?: string; eventId?: string | number
  eventName?: string; complexId?: string | number; complexName?: string; subject?: string; checkDate?: string
  bizState?: string; approveState?: string; createTime?: string
}
interface InspectionItemVo {
  templateItemId?: string | number; detailId?: string | number; checkContent?: string; checkArea?: string
  fillType?: string; fillOptions?: string; unit?: string; fillValue?: string | number; fillNumeric?: number | string; sortNo?: number
}
interface InspectionVo extends InspectionRow { items?: InspectionItemVo[] }
interface RescueRow {
  rescueId: string | number; rescueNo?: string; complexId?: string | number; complexName?: string
  regionName?: string; contactName?: string; contactPhone?: string; urgentLevel?: string
  dangerDesc?: string; supportDesc?: string; attachUrl?: string; status?: string; createTime?: string
}

function toItems(raw?: InspectionItemVo[]): FloodItem[] {
  return (raw ?? []).map(it => ({
    templateItemId: String(it.templateItemId ?? ''),
    detailId: it.detailId != null ? String(it.detailId) : undefined,
    label: String(it.checkContent || it.checkArea || '检查项'),
    fillType: String(it.fillType ?? '1'),
    fillOptions: it.fillOptions ? String(it.fillOptions).split(/[,，]/).filter(Boolean) : undefined,
    unit: it.unit,
    value: it.fillValue != null ? String(it.fillValue) : (it.fillNumeric != null ? String(it.fillNumeric) : ''),
    sortNo: it.sortNo,
  }))
}
function inspectionRowToRecord(row: InspectionRow): FloodRecord {
  const kind = KIND_BY_STAGE[String(row.inspectionStage)] ?? 'pre'
  return {
    id: String(row.inspectionId), kind, status: 'submitted',
    createdAt: row.createTime ?? new Date().toISOString(),
    inspectionNo: row.inspectionNo, subject: row.subject,
    complexId: row.complexId != null ? String(row.complexId) : undefined,
    complexName: row.complexName,
    eventId: row.eventId != null ? String(row.eventId) : undefined,
    eventName: row.eventName, checkDate: row.checkDate,
    bizState: row.bizState, approveState: row.approveState,
  }
}
function rescueRowToRecord(row: RescueRow): FloodRecord {
  return {
    id: String(row.rescueId), kind: 'rescue', status: 'submitted',
    createdAt: row.createTime ?? new Date().toISOString(),
    inspectionNo: row.rescueNo,
    complexId: row.complexId != null ? String(row.complexId) : undefined,
    complexName: row.complexName,
    rescue: {
      contactName: row.contactName, contactPhone: row.contactPhone, urgentLevel: row.urgentLevel,
      dangerDesc: row.dangerDesc, supportDesc: row.supportDesc, attachUrl: row.attachUrl,
    },
  }
}

export function createFloodStore(storage: StoragePort, mode: string = 'demo') {
  return defineStore('flood', () => {
    const isRemote = mode !== 'demo'
    function read(): SavedData {
      const data = storage.get(key) as SavedData | undefined
      if (data == null || data === ('' as unknown)) return { version: 1, drafts: {} }
      if (data.version !== 1) throw new Error('本地数据版本不兼容，请导出备份后清理本地演示数据')
      if (!data.drafts || typeof data.drafts !== 'object' || Array.isArray(data.drafts) || (data.records != null && !Array.isArray(data.records))) throw new Error('本地数据损坏，请备份后清理本地演示数据')
      return JSON.parse(JSON.stringify(data)) as SavedData
    }
    function normalizeDraft(entry: DraftEntry | FormValues): DraftEntry {
      const candidate = entry as DraftEntry
      if (candidate && typeof candidate === 'object' && 'values' in candidate && candidate.values && typeof candidate.values === 'object') return { values: candidate.values, savedAt: String(candidate.savedAt ?? '') }
      return { values: entry as FormValues, savedAt: '' }
    }
    function saveDraft(kind: InspectionType, values: FormValues) {
      validatePhotos(values)
      const data = read()
      data.drafts[kind] = { values: JSON.parse(JSON.stringify(values)), savedAt: new Date().toISOString() }
      storage.set(key, data)
    }
    function loadDraft(kind: InspectionType) {
      const entry = read().drafts[kind]
      return entry ? normalizeDraft(entry).values : null
    }
    function draftSavedAt(kind: InspectionType) {
      const entry = read().drafts[kind]
      return entry ? normalizeDraft(entry).savedAt || null : null
    }
    function validatePhotos(values: FormValues) {
      const photos = values.photos
      if (photos == null) return
      if (!Array.isArray(photos) || photos.length > 6 || photos.some(photo => photo.status !== 'done' || !photo.url)) throw new Error('照片尚未保存成功，请重试或删除；最多6张')
    }
    let submitting = false

    async function submitInspection(kind: InspectionType, values: FormValues): Promise<FloodRecord> {
      if (submitting) throw new Error('正在提交，请稍候')
      submitting = true
      try {
        if (isRemote) return await submitInspectionRemote(kind, values)
        await Promise.resolve()
        validatePhotos(values)
        if (hasDateField(kind) && !/^\d{4}-\d{2}-\d{2}$/.test(String(values.date ?? ''))) throw new Error('请选择填报日期')
        for (const value of Object.values(values)) {
          if (typeof value === 'number' && (!Number.isInteger(value) || value < 0)) throw new Error('数量必须为非负整数')
        }
        const data = read()
        const record: FloodRecord = { id: `FX-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, kind, status: 'submitted', values: JSON.parse(JSON.stringify(values)), createdAt: new Date().toISOString() }
        data.records = [record, ...(data.records ?? [])]
        delete data.drafts[kind]
        storage.set(key, data)
        return record
      } finally { submitting = false }
    }

    async function submitInspectionRemote(kind: InspectionType, values: FormValues): Promise<FloodRecord> {
      // values 约定：{ eventId, complexId, checkDate?, haveDanger?, items: FloodItem[] 或 {templateItemId->value} }
      if (!values.eventId) throw new Error('缺少预警事件')
      if (!values.complexId) throw new Error('请选择物业管理区域')
      const items = normalizeItems(values)
      if (items.length === 0) throw new Error('请至少填写一个检查项')
      const payload = {
        inspectionStage: STAGE[kind],
        subject: 'property',
        eventId: Number(values.eventId),
        complexId: Number(values.complexId),
        haveDanger: values.haveDanger != null ? String(values.haveDanger) : '0',
        checkDate: values.checkDate || undefined,
        items: items.map(it => ({ templateItemId: Number(it.templateItemId), fillType: it.fillType, fillValue: it.value })),
      }
      const saved = await request<number | string>('/v2.0/safety/flood/inspection/save', { method: 'POST', data: payload })
      await request('/v2.0/safety/flood/inspection/submit', { method: 'POST', data: { id: Number(saved) } })
      const record = await getRecordAsync(String(saved), kind)
      if (record) { try { const d = read(); delete d.drafts[kind]; storage.set(key, d) } catch { /* ignore */ } return record }
      return { id: String(saved), kind, status: 'submitted', createdAt: new Date().toISOString(), complexId: String(values.complexId), eventId: String(values.eventId), items }
    }

    function normalizeItems(values: FormValues): FloodItem[] {
      const raw = values.items
      if (Array.isArray(raw)) return (raw as FloodItem[]).filter(it => it && it.templateItemId)
      // 也接受模板表单直接塞 FloodItem[]
      return []
    }

    function getRecord(id: string) { return read().records?.find(record => record.id === id) ?? null }
    function getDraftByKey(id: string) {
      if (!id.startsWith('draft-')) return null
      const kind = id.slice(6) as InspectionType
      if (kind !== 'pre' && kind !== 'mid' && kind !== 'post') return null
      const entry = read().drafts[kind]
      if (!entry) return null
      const draft = normalizeDraft(entry)
      return { id, kind, status: 'draft' as const, values: draft.values, createdAt: draft.savedAt } satisfies FloodRecord
    }
    function localDrafts(query: HistoryQuery): FloodRecord[] {
      const data = read()
      return Object.entries(data.drafts).map(([kind, entry]) => {
        const draft = normalizeDraft(entry)
        return { id: `draft-${kind}`, kind: kind as InspectionType, status: 'draft' as const, values: draft.values, createdAt: draft.savedAt }
      }).filter(item => query.kinds.includes(item.kind) && (query.status === 'all' || item.status === query.status) && (!query.keyword || JSON.stringify(item.values).includes(query.keyword)))
    }
    function matchQuery(query: HistoryQuery) {
      const data = read()
      return [...localDrafts(query), ...(data.records ?? [])].filter(item => query.kinds.includes(item.kind) && (query.status === 'all' || item.status === query.status) && (!query.keyword || JSON.stringify(item.values ?? item).includes(query.keyword)))
    }
    async function fetchHistoryPage(query: HistoryQuery & { pageNum: number; pageSize: number }) {
      if (isRemote) return await fetchHistoryRemote(query)
      const all = matchQuery(query)
      const start = (query.pageNum - 1) * query.pageSize
      return { items: all.slice(start, start + query.pageSize), total: all.length, hasMore: start + query.pageSize < all.length }
    }
    async function fetchHistoryRemote(query: HistoryQuery & { pageNum: number; pageSize: number }) {
      const wantsRescue = query.kinds.includes('rescue')
      const inspectionKinds = query.kinds.filter(k => k !== 'rescue') as InspectionType[]
      let records: FloodRecord[] = []
      if (inspectionKinds.length > 0) {
        const page = await request<PageVo<InspectionRow>>(`/v2.0/safety/flood/inspection/page?pageNum=${query.pageNum}&pageSize=${query.pageSize}`, { raw: true })
        records.push(...(page.rows ?? []).map(inspectionRowToRecord).filter(r => inspectionKinds.includes(r.kind as InspectionType)))
      }
      if (wantsRescue) {
        const page = await request<PageVo<RescueRow>>(`/v2.0/safety/flood/rescue/page?pageNum=${query.pageNum}&pageSize=${query.pageSize}`, { raw: true })
        records.push(...(page.rows ?? []).map(rescueRowToRecord))
      }
      if (query.keyword) records = records.filter(r => `${r.inspectionNo ?? ''}${r.complexName ?? ''}`.includes(query.keyword as string))
      return { items: records, total: records.length, hasMore: records.length >= query.pageSize }
    }
    async function countHistory(query: HistoryQuery) {
      if (isRemote) {
        const page = await fetchHistoryRemote({ ...query, pageNum: 1, pageSize: 1000 })
        return page.total
      }
      return matchQuery(query).length
    }
    async function submitRescue(values: FormValues): Promise<FloodRecord> {
      if (submitting) throw new Error('正在提交，请稍候')
      submitting = true
      try {
        if (isRemote) return await submitRescueRemote(values)
        await Promise.resolve()
        if (!String(values.contact ?? '').trim()) throw new Error('请填写联系人')
        if (!/^1\d{10}$/.test(String(values.phone ?? ''))) throw new Error('请填写有效的11位联系电话')
        if (!['一般', '紧急', '特级'].includes(String(values.level))) throw new Error('请选择紧急程度')
        if (!String(values.danger ?? '').trim() || !String(values.support ?? '').trim()) throw new Error('请填写险情与支援描述')
        if (!Array.isArray(values.photos) || values.photos.length === 0) throw new Error('请上传现场照片')
        validatePhotos(values)
        const data = read()
        const record: FloodRecord = { id: `QY-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, kind: 'rescue', status: 'submitted', values: JSON.parse(JSON.stringify(values)), createdAt: new Date().toISOString() }
        data.records = [record, ...(data.records ?? [])]
        storage.set(key, data)
        return record
      } finally { submitting = false }
    }
    async function submitRescueRemote(values: FormValues): Promise<FloodRecord> {
      if (!String(values.contact ?? '').trim()) throw new Error('请填写联系人')
      if (!/^1\d{10}$/.test(String(values.phone ?? ''))) throw new Error('请填写有效的11位联系电话')
      if (!['一般', '紧急', '特级'].includes(String(values.level))) throw new Error('请选择紧急程度')
      if (!String(values.danger ?? '').trim() || !String(values.support ?? '').trim()) throw new Error('请填写险情与支援描述')
      if (!values.complexId) throw new Error('请选择物业管理区域')
      const payload = {
        complexId: Number(values.complexId),
        contactName: String(values.contact),
        contactPhone: String(values.phone),
        urgentLevel: URGENT[String(values.level)],
        dangerDesc: String(values.danger),
        supportDesc: String(values.support),
      }
      const saved = await request<number | string>('/v2.0/safety/flood/rescue/save', { method: 'POST', data: payload })
      await request('/v2.0/safety/flood/rescue/submit', { method: 'POST', data: { id: Number(saved) } })
      const record = await getRecordAsync(String(saved), 'rescue')
      return record ?? { id: String(saved), kind: 'rescue', status: 'submitted', createdAt: new Date().toISOString(), complexId: String(values.complexId), rescue: { contactName: payload.contactName, contactPhone: payload.contactPhone, urgentLevel: payload.urgentLevel, dangerDesc: payload.dangerDesc, supportDesc: payload.supportDesc } }
    }

    // ===== remote 专用辅助 API =====
    async function login(username: string, password: string): Promise<void> {
      const encrypted = aesEncrypt(password)
      const res = await authRequest<{ accessToken?: string; token?: string }>('/v2.0/security/auth/login', {
        method: 'POST', data: { username, password: encrypted }, token: false, raw: true,
      })
      const body = res as unknown as { code?: number; msg?: string; data?: { accessToken?: string; token?: string } }
      if (body && typeof body === 'object' && 'code' in body && body.code !== 200) throw new Error(body.msg || '登录失败')
      const token = body?.data?.accessToken ?? body?.data?.token
      if (!token) throw new Error('登录失败：未获取到令牌')
      setToken(token)
    }
    async function fetchEvents(): Promise<EventVo[]> {
      const page = await request<PageVo<EventVo>>('/v2.0/safety/flood/event/page?pageNum=1&pageSize=50', { raw: true })
      return page.rows ?? []
    }
    async function fetchTemplate(kind: InspectionType, eventId?: string): Promise<FloodTemplate> {
      const stage = STAGE[kind]
      let ev = eventId
      if (!ev) {
        const events = await fetchEvents()
        const hit = events.find(e => String(e.stage) === stage && String(e.bizState) === '2') || events.find(e => String(e.stage) === stage)
        if (!hit) throw new Error('当前阶段暂无可填报的预警事件')
        ev = String(hit.eventId)
      }
      const items = await request<InspectionItemVo[]>(`/v2.0/safety/flood/inspection/template?eventId=${ev}&inspectionStage=${stage}`)
      return { kind, eventId: ev, stage, items: toItems(items) }
    }
    async function searchComplex(keyword: string): Promise<{ code: string; name: string }[]> {
      if (!keyword) return []
      const list = await request<{ code: string | number; name: string; extra?: string }[]>(`/v2.0/safety/flood/common/complex/options?complexName=${encodeURIComponent(keyword)}`)
      return (list ?? []).map(c => ({ code: String(c.code), name: String(c.name) }))
    }
    async function getRecordAsync(id: string, kind: HistoryKind): Promise<FloodRecord | null> {
      try {
        if (kind === 'rescue') {
          const vo = await request<RescueRow & { rescueId?: string | number }>(`/v2.0/safety/flood/rescue/${id}`)
          return rescueRowToRecord(vo as RescueRow)
        }
        const vo = await request<InspectionVo>(`/v2.0/safety/flood/inspection/${id}`)
        const rec = inspectionRowToRecord(vo)
        rec.items = toItems(vo.items)
        return rec
      } catch { return null }
    }

    return {
      saveDraft, loadDraft, draftSavedAt, submitInspection, submitRescue, getRecord, getDraftByKey, fetchHistoryPage, countHistory,
      login, fetchEvents, fetchTemplate, searchComplex, getRecordAsync,
    }
  })
}
